class Solution {
    public int longestCycle(int[] edges){
        int[] visitedTime=new int[edges.length];
        int time=1,answer=-1;
        for(int start=0;start<edges.length;start++)if(visitedTime[start]==0){
            int startTime=time,node=start;
            while(node!=-1&&visitedTime[node]==0){
                visitedTime[node]=time++;
                node=edges[node];
            }
            if(node!=-1&&visitedTime[node]>=startTime)answer=Math.max(answer,time-visitedTime[node]);
        }
        return answer;
    }
}

